using System.Windows;
using VisionFramework;
namespace VisionEditor;
public partial class MainWindow
{
 readonly HashSet<SubprogramCallWindow> groupConfigurationWindows=new();
 SubprogramCallWindow CreateSubprogramCallWindow(string id)=>CreateBoundGroupWindow(doc.CurrentProcedureId,id,groupEditsShareRoot:true);
 SubprogramCallWindow CreateBoundGroupWindow(string flow,string id,bool groupEditsShareRoot=false)
 {
  string solution=doc.SolutionId;
  ProcedureDocument OwnerFlow()=>ConfigurationProcedure(flow);
  NodeDocument Node()=>OwnerFlow().Nodes.Single(n=>n.Id==id);
  void Guard(){if(windowClosed||isLocked||activeRun is not null||doc.SolutionId!=solution||(doc.CurrentProcedureId!=flow&&doc.CurrentProcedureId!=Node().Call?.ProcedureId))throw new InvalidOperationException("当前Group不可编辑。");}
  void ConfigurationEdit(Action change){if(groupEditsShareRoot)change();else doc.ExecuteConfigurationEdit(_=>change());}
  void OwnerEdit(Action<VisionEditor.Core.GraphEditorDocument> change){Guard();ConfigurationEdit(()=>doc.EditProcedure(flow,change));}
  IEnumerable<WorkflowSourceOption> Sources(DataKind kind){
   var front=GroupFrontNodes(OwnerFlow(),id);
   foreach(var s in WorkflowSources(flow,kind).Where(s=>front.Contains(s.NodeId)))yield return s with{Reference=new(WorkflowSourceKind.NodeOutput,s.NodeId,s.Port)};
   if(kind==DataKind.Integer&&OwnerFlow().GroupOwner is not null)yield return new("group:loop","LoopIndex",kind,"Group.LoopIndex"){Reference=new(WorkflowSourceKind.GroupLoopIndex,"LoopIndex")};
   foreach(var v in OwnerFlow().Configuration.Variables.Where(v=>WorkflowSubscriptions.VariableKind(v.Type)==kind))yield return new("variable:"+v.Id,v.Name,kind,"局部变量."+v.Name){Reference=new(WorkflowSourceKind.LocalVariable,v.Id)};
   foreach(var v in OwnerFlow().Configuration.Inputs.Where(v=>v.Kind==kind))yield return new("input:"+v.Id,v.Name,kind,"流程输入."+v.Name){Reference=new(WorkflowSourceKind.WorkflowInput,v.Id),Cardinality=v.Cardinality};
  }
  ProcedureDocument Body()=>ConfigurationProcedure(Node().Call!.ProcedureId);
  IEnumerable<WorkflowSourceOption> BodySources(DataKind? kind)=>Body().Nodes.SelectMany(n=>modules.GetDescriptor(n).Outputs.Where(p=>!kind.HasValue||DataKinds.CanFlow(p.Kind,kind.Value)).Select(p=>new WorkflowSourceOption(n.Id,p.Name,p.Kind,n.Name+"."+p.Name){Cardinality=p.Cardinality,NodeName=n.Name}));
  IEnumerable<GroupComparisonOption> CompareSources(DataKind kind){
   foreach(var option in Sources(kind)){var reference=option.Reference!;yield return new("父级."+option.Label,new(false,reference),WorkflowSubscriptions.SourceCardinality(OwnerFlow(),modules,reference)==ValueCardinality.Array);}
   foreach(var output in Node().Call!.Outputs.Where(p=>p.Kind==kind))yield return new("Group."+output.Name,new(false,new(WorkflowSourceKind.NodeOutput,id,output.Name),Self:true),output.Cardinality==ValueCardinality.Array);
   foreach(var option in BodySources(kind))yield return new("内部."+option.Label,new(true,new(WorkflowSourceKind.NodeOutput,option.NodeId,option.Port)),option.Cardinality==ValueCardinality.Array);
   foreach(var v in Body().Configuration.Variables.Where(v=>WorkflowSubscriptions.VariableKind(v.Type)==kind))yield return new("内部.局部变量."+v.Name,new(true,new(WorkflowSourceKind.LocalVariable,v.Id)));
   foreach(var v in Body().Configuration.Inputs.Where(v=>v.Kind==kind))yield return new("内部.输入."+v.Name,new(true,new(WorkflowSourceKind.WorkflowInput,v.Id)),v.Cardinality==ValueCardinality.Array);
   if(kind==DataKind.Integer)yield return new("内部.Group.LoopIndex",new(true,new(WorkflowSourceKind.GroupLoopIndex,"LoopIndex")));
  }
  void Invalidate(){InvalidateToolDebugResult(flow,id);if(workflowSessions.TryGetValue(flow,out var old))workflowSessions[flow]=old with{Calls=old.Calls.Where(c=>c.Key!=id).ToDictionary(c=>c.Key,c=>c.Value)};ClearWorkflowCallResults(Body().Id);results.Clear();RefreshRight();}
  var window=new SubprogramCallWindow(OwnerFlow,Node,()=>doc.Document.Procedures,target=>{OwnerEdit(d=>d.ConfigureSubprogram(id,target));},(port,source)=>{OwnerEdit(d=>d.SetSubprogramInput(id,port,source));Invalidate();},Sources,async()=>{if(activeRun is not null)throw new InvalidOperationException("流程正在运行。");if(Body().GroupOwner is null){await RunLegacyGroupProcedure(flow);if(!workflowSessions.TryGetValue(flow,out var session)||!session.Calls.ContainsKey(id))throw new InvalidOperationException(StatusText.Text);}else await RunGroupDebug(flow,id,solution);},()=>{if(doc.SolutionId==solution&&runningProcedureId==flow)activeRun?.Cancel();},()=>workflowSessions.GetValueOrDefault(flow)?.Calls.GetValueOrDefault(id),(key,value)=>{OwnerEdit(d=>d.SetParameter(id,key,value));Invalidate();},(key,source)=>{Guard();var config=OwnerFlow().Configuration;var remaining=config.Subscriptions.Where(b=>b.NodeId!=id||b.Target!=key||!b.IsParameter);ConfigurationEdit(()=>doc.SetWorkflowConfiguration(flow,config with{Subscriptions=(source is null?remaining:remaining.Append(new(id,key,true,source))).ToArray()}));},(enabled,type,comparison,bindings)=>{OwnerEdit(d=>d.SetGroupBreak(id,enabled,type,comparison,bindings));Invalidate();},CompareSources,configuration=>{Guard();ConfigurationEdit(()=>doc.SetWorkflowConfiguration(Body().Id,configuration));Invalidate();},BodySources,modules,(nodeId,key,value)=>{Guard();var target=Body().Nodes.Single(n=>n.Id==nodeId);var values=target.Parameters.ToDictionary(p=>p.Key,p=>p.Value.Clone());values[key]=value;ConfigurationEdit(()=>doc.SetProcedureNodeParameters(Body().Id,nodeId,values));Invalidate();},(nodeId,key,isInput,source)=>{Guard();var body=Body();if(isInput)ConfigurationEdit(()=>doc.SetProcedureInputSubscription(body.Id,nodeId,key,source));else{var remaining=body.Configuration.Subscriptions.Where(b=>b.NodeId!=nodeId||b.Target!=key||!b.IsParameter);ConfigurationEdit(()=>doc.SetWorkflowConfiguration(body.Id,body.Configuration with{Subscriptions=(source is null?remaining:remaining.Append(new(nodeId,key,true,source))).ToArray()}));}Invalidate();},(inputs,bindings)=>{OwnerEdit(d=>d.ConfigureOwnedGroupInputs(id,inputs,bindings));Invalidate();},(proxy,value)=>{Guard();ConfigurationEdit(()=>doc.SetGroupRunParameterValue(Body().Id,proxy,value));Invalidate();},(proxy,source)=>{Guard();ConfigurationEdit(()=>doc.SetGroupRunParameterSource(Body().Id,proxy,source));Invalidate();},(proxy,values,rois)=>{Guard();ConfigurationEdit(()=>doc.SetGroupRunComplexValue(Body().Id,proxy,values,rois));Invalidate();}){Owner=this};window.DedicatedParameterEditor=(node,spec,save)=>spec.Editor?.Kind==ParameterEditorKind.Roi&&plugins.Find(node.ModuleId)is VisionPluginContracts.IWpfToolParameterEditorFactory factory?factory.CreateParameterEditor(new(node,spec,ResolveGroupToolImage(Body().Id,node.Id),save)):null;window.GroupToolImage=nodeId=>ResolveGroupToolImage(Body().Id,nodeId);window.HasGroupToolEditor=nodeId=>plugins.Find(Body().Nodes.Single(n=>n.Id==nodeId).ModuleId)is VisionPluginContracts.IWpfToolEditorFactory;window.OpenGroupToolEditor=nodeId=>OpenOwnedGroupToolEditor(flow,id,Body().Id,nodeId,window.ActiveConfigurationOwner);groupConfigurationWindows.Add(window);window.Closed+=(_,_)=>groupConfigurationWindows.Remove(window);return window;
 }
 static HashSet<string> GroupFrontNodes(ProcedureDocument procedure,string nodeId){
  var links=ProcedureGraph.ExecutionEdges(procedure).Select(e=>(e.FromNode,e.ToNode))
   .Concat(procedure.Connections.Select(e=>(e.FromNode,e.ToNode))).ToArray();
  var front=new HashSet<string>(StringComparer.Ordinal);var pending=new Stack<string>();pending.Push(nodeId);
  while(pending.Count>0){var current=pending.Pop();foreach(var link in links.Where(e=>e.ToNode==current))if(front.Add(link.FromNode))pending.Push(link.FromNode);}
  front.Remove(nodeId);return front;
 }
 async Task RunGroupDebug(string flow,string id,string solution){
  if(windowClosed||isLocked||doc.SolutionId!=solution||activeRun is not null||toolDebugSessions.Any(s=>s.IsBusy))throw new InvalidOperationException("当前Group不可运行。");
  var cached=ToolDebugInputs(flow);var input=workflowSessions.GetValueOrDefault(flow)?.WorkflowInputs;var index=workflowSessions.GetValueOrDefault(flow)?.GroupLoopIndex;var workspace=new SolutionWorkspace(doc.Document,doc.BaseDirectory);var cancellation=new CancellationTokenSource();activeRun=cancellation;runningProcedureId=flow;continuousRun=false;InvalidateToolDebugResult(flow,id);if(workflowSessions.TryGetValue(flow,out var previous))workflowSessions[flow]=previous with{Calls=previous.Calls.Where(c=>c.Key!=id).ToDictionary(c=>c.Key,c=>c.Value)};ClearWorkflowCallResults(ConfigurationProcedure(flow).Nodes.Single(n=>n.Id==id).Call!.ProcedureId);RefreshAll();
  try{var session=await Task.Run(()=>new GroupDebugExecutor(modules).RunAsync(workspace,flow,id,cached,input,cancellation.Token,index));if(!windowClosed&&doc.SolutionId==solution){StoreWorkflowCallResults(flow,session);foreach(var record in cached)if(record.NodeId!=id&&!toolDebugInvalid.Contains(DebugIdentity(flow,record.NodeId)))toolDebugRecords[DebugIdentity(flow,record.NodeId)]=record;foreach(var record in session.Nodes)StoreToolDebugResult(flow,record);StatusText.Text="Group独立运行："+session.Status;if(!session.Calls.ContainsKey(id))throw new InvalidOperationException(string.Join("；",session.Nodes.Where(n=>n.ErrorCode is not null).Select(n=>n.ErrorCode+": "+n.Message)));}}
  catch(Exception error){if(!windowClosed&&doc.SolutionId==solution)StatusText.Text="Group独立运行失败："+error.Message;throw;}
  finally{FinishWorkflowRun(cancellation);}
 }
 void OpenSubprogramCall(string id){if(isLocked||activeRun is not null||parameterEditorOpen)return;if(doc.CurrentProcedure.Nodes.Single(n=>n.Id==id).Call is null){Safe(()=>{var parent=doc.CurrentProcedureId;doc.EnterOwnedGroup(id);doc.SelectProcedure(parent);});if(doc.CurrentProcedure.Nodes.FirstOrDefault(n=>n.Id==id)?.Call is null)return;}ResetEditingGesture();var window=CreateSubprogramCallWindow(id);parameterEditorOpen=true;try{doc.ExecuteConfigurationEdit(_=>{window.ShowDialog();});}finally{parameterEditorOpen=false;}if(window.EnterProcedureId is {} target)SelectWorkflow(target);}
 void EnterSubprogram(string id){var groupNode=doc.CurrentProcedure.Nodes.Single(n=>n.Id==id);if(!groupNode.Enabled||isLocked||activeRun is not null)return;var call=groupNode.Call;if(call is null){Safe(()=>doc.EnterOwnedGroup(id));}else if(doc.Document.Procedures.FirstOrDefault(p=>p.Id==call.ProcedureId)?.GroupOwner is not null){Safe(()=>doc.EnterOwnedGroup(id));}else SelectWorkflow(call.ProcedureId);}
}
